using NUnit.Framework;
using SaferAccessors.Tests;

namespace SaferAccessors.Analysis.Tests.Generators;

internal static class MethodAccessorGeneratorTests
{
	[Test]
	public static async Task GenerateWithInstanceMethodAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private int GetValue(string key) => 22;
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension(global::Test self)
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Method, Name = "GetValue")]
					public extern int GetValue(string key);
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}

	[Test]
	public static async Task GenerateWithInstanceMethodOnGenericTypeAsync()
	{
		var code =
			"""
			using SaferAccessors;

			[assembly: UnsafeAccessorMap(typeof(Test<>))]

			public class Test<T>
			{
				private int Compute(T value) => value?.GetHashCode() ?? 0;
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension<T>(global::Test<T> self)
				{
					public int Compute(T value) =>
						TestAccessors<T>.Compute(self, value);
				}
				
				private static class TestAccessors<T>
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Method, Name = "Compute")]
					public static extern int Compute(global::Test<T> self, T value);
						
				}
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_T_Accessors.g.cs", generatedCode)],
			[]);
	}

